package run.ikaros.finance; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Mono; import run.ikaros.common.NotFoundException; @Service public class FinanceLedgerAccessService{private final LedgerRepository ledgers;private final LedgerMemberRepository members;public FinanceLedgerAccessService(LedgerRepository l,LedgerMemberRepository m){ledgers=l;members=m;}public Mono<LedgerMemberRole> access(UUID actor,UUID ledgerId){return ledgers.findById(ledgerId).flatMap(l->l.ownerId().equals(actor)?Mono.just(LedgerMemberRole.EDITOR):members.findByLedgerIdAndPrincipalId(ledgerId,actor).map(LedgerMemberEntity::role)).switchIfEmpty(Mono.error(new NotFoundException("Ledger 不存在或无权访问")));}public Mono<Void> requireEditor(UUID actor,UUID ledgerId){return access(actor,ledgerId).filter(r->r==LedgerMemberRole.EDITOR).switchIfEmpty(Mono.error(new NotFoundException("Ledger 不存在或无写入权限"))).then();}}
